export interface OrderablePart {
  index: number;
  characterIndex: number;
}

export interface ManualOrderResolution<T extends OrderablePart> {
  paintParts: readonly T[];
  partRevealPositions: ReadonlyMap<number, number>;
  characterRevealPositions: readonly number[];
}

interface ParsedEndpoint {
  isCharacter: boolean;
  hadPrefix: boolean;
  userIndex: number;
}

const kMaximumNativeInteger = 2147483647;

function parseEndpoint(value: string): ParsedEndpoint | undefined {
  if (value.length === 0) {
    return undefined;
  }
  const prefix = value[0];
  const hasCharacterPrefix = prefix === "c" || prefix === "C";
  const hasPartPrefix = prefix === "p" || prefix === "P";
  const hadPrefix = hasCharacterPrefix || hasPartPrefix;
  const numberText = hadPrefix ? value.slice(1) : value;
  if (!/^[0-9]+$/.test(numberText)) {
    return undefined;
  }
  const userIndex = Number(numberText);
  if (!Number.isSafeInteger(userIndex) || userIndex <= 0 || userIndex > kMaximumNativeInteger) {
    return undefined;
  }
  return { isCharacter: hasCharacterPrefix, hadPrefix, userIndex };
}

function parseManualPartOrder(
  text: string,
  partsByCharacter: readonly (readonly number[])[],
  validPartIndices: ReadonlySet<number>,
  maximumPartIndex: number,
): number[] {
  const result: number[] = [];
  const seen = new Set<number>();
  const appendPart = (partIndex: number): void => {
    if (validPartIndices.has(partIndex) && !seen.has(partIndex)) {
      seen.add(partIndex);
      result.push(partIndex);
    }
  };
  const appendEndpoint = (isCharacter: boolean, userIndex: number): void => {
    if (isCharacter) {
      for (const partIndex of partsByCharacter[userIndex] ?? []) {
        appendPart(partIndex);
      }
    } else if (userIndex <= maximumPartIndex) {
      appendPart(userIndex);
    }
  };

  for (const token of text.split(/[,	\n\v\f\r ]+/)) {
    if (token.length === 0) {
      continue;
    }
    const dashPosition = token.indexOf("-");
    if (dashPosition < 0) {
      const endpoint = parseEndpoint(token);
      if (endpoint !== undefined) {
        appendEndpoint(endpoint.isCharacter, endpoint.userIndex);
      }
      continue;
    }

    const start = parseEndpoint(token.slice(0, dashPosition));
    const end = parseEndpoint(token.slice(dashPosition + 1));
    if (start === undefined || end === undefined) {
      continue;
    }
    if (!start.hadPrefix && end.hadPrefix) {
      start.isCharacter = end.isCharacter;
    } else if (start.hadPrefix && !end.hadPrefix) {
      end.isCharacter = start.isCharacter;
    }
    if (start.isCharacter !== end.isCharacter) {
      continue;
    }
    const firstIndex = Math.min(start.userIndex, end.userIndex);
    const lastIndex = Math.min(
      Math.max(start.userIndex, end.userIndex),
      start.isCharacter ? partsByCharacter.length - 1 : maximumPartIndex,
    );
    for (let userIndex = firstIndex; userIndex <= lastIndex; userIndex += 1) {
      appendEndpoint(start.isCharacter, userIndex);
    }
  }
  return result;
}

export function resolveManualOrder<T extends OrderablePart>(
  parts: readonly T[],
  characterCount: number,
  text: string,
): ManualOrderResolution<T> {
  const normalizedCharacterCount = Math.max(characterCount, 0);
  const partsByCharacter = Array.from(
    { length: normalizedCharacterCount + 1 },
    (): number[] => [],
  );
  const partByIndex = new Map<number, T>();
  for (const part of parts) {
    if (Number.isInteger(part.index) && part.index > 0 && !partByIndex.has(part.index)) {
      partByIndex.set(part.index, part);
      if (part.characterIndex >= 1 && part.characterIndex <= normalizedCharacterCount) {
        partsByCharacter[part.characterIndex].push(part.index);
      }
    }
  }
  for (const characterParts of partsByCharacter) {
    characterParts.sort((first, second) => first - second);
  }

  const basePartIndices = [...partByIndex.keys()].sort((first, second) => first - second);
  const maximumPartIndex = basePartIndices.at(-1) ?? 0;
  const manualPartIndices = parseManualPartOrder(
    text,
    partsByCharacter,
    new Set(basePartIndices),
    maximumPartIndex,
  );
  const placed = new Set(manualPartIndices);
  const rankedPartIndices = [
    ...manualPartIndices,
    ...basePartIndices.filter((partIndex) => !placed.has(partIndex)),
  ];
  const partRevealPositions = new Map<number, number>();
  rankedPartIndices.forEach((partIndex, rank) => {
    partRevealPositions.set(partIndex, rank + 1);
  });

  const characterOrder = Array.from({ length: normalizedCharacterCount }, (_, index) => index + 1);
  const characterSortKeys = characterOrder.map((characterIndex) => {
    const partRanks = partsByCharacter[characterIndex]
      .map((partIndex) => partRevealPositions.get(partIndex) ?? 0)
      .filter((rank) => rank > 0);
    return partRanks.length > 0 ? Math.min(...partRanks) : maximumPartIndex + characterIndex;
  });
  characterOrder.sort((first, second) =>
    characterSortKeys[first - 1] - characterSortKeys[second - 1] || first - second,
  );
  const characterRevealPositions = Array.from({ length: normalizedCharacterCount }, () => 0);
  characterOrder.forEach((characterIndex, rank) => {
    characterRevealPositions[characterIndex - 1] = rank + 1;
  });

  // Native paints whole characters in characterRevealPosition order and only sorts parts within
  // each character (ProjectionStage's applyManualCharacterOrder over TextDrawStage's per-character
  // partDrawOrder walk). Walking partsByCharacter in raw index order instead would keep a character
  // listed first in the manual order from moving behind the others.
  const orderedPartIndices = characterOrder.flatMap((characterIndex) =>
    [...partsByCharacter[characterIndex]].sort(
      (first, second) =>
        (partRevealPositions.get(first) ?? first) - (partRevealPositions.get(second) ?? second),
    ),
  );
  const orderedPartIndexSet = new Set(orderedPartIndices);
  const paintParts = [
    ...orderedPartIndices
      .map((partIndex) => partByIndex.get(partIndex))
      .filter((part): part is T => part !== undefined),
    ...parts.filter((part) => !orderedPartIndexSet.has(part.index)),
  ];

  return { paintParts, partRevealPositions, characterRevealPositions };
}
